from scipy.optimize import least_squares
t=np.asarray(df['t']);A=np.asarray(df['A']);y=np.asarray(df['dA_dt'])
fams={
 'a+bA^p exp(-qA^s)': (lambda g: g[0]+g[1]*A**g[2]*np.exp(-g[3]*A**g[4]), 5),
 'a+bA^p exp(-qA)/(1+rA)': (lambda g: g[0]+g[1]*A**g[2]*np.exp(-g[3]*A)/(1+g[4]*A), 5),
 'a+bA^p exp(-qA)+dA': (lambda g: g[0]+g[1]*A**g[2]*np.exp(-g[3]*A)+g[4]*A, 5),
 'a+bA^p exp(-qA)+d log(1+A)': (lambda g: g[0]+g[1]*A**g[2]*np.exp(-g[3]*A)+g[4]*np.log(1+A), 5),
 'a+bA^p exp(-qA)+d/A': (lambda g: g[0]+g[1]*A**g[2]*np.exp(-g[3]*A)+g[4]/A, 5),
 'a+bA exp(-qA)+d A^2 exp(-rA)': (lambda g: g[0]+g[1]*A*np.exp(-g[2]*A)+g[3]*A**2*np.exp(-g[4]*A), 5),
}
for name,(g,n) in fams.items():
    def r(q):
        m=q[0]*np.log(1+q[1]*A)*t+q[2]*np.log(1+A)**2
        return m+np.sqrt(t)*g(q[3:])-y
    best=None
    for s in range(10):
        rs=np.random.RandomState(s)
        x0=np.r_[rs.uniform(-1,1),rs.uniform(1,2),rs.uniform(1,3),rs.normal(0,2,n)]
        try:
            with np.errstate(all='ignore'):
                rr=least_squares(r,x0)
            if np.all(np.isfinite(rr.fun)) and (best is None or rr.cost<best.cost): best=rr
        except Exception: pass
    if best is not None: print(name,'NMSE %.3e'%(np.mean(best.fun**2)/np.var(y)), best.x.round(4))
    else: print(name,'none')

